let balance = 100;
let lock = Promise.resolve();
function withdraw(amt) {
  const run = lock.then(async () => {
    if (balance >= amt) {
      await Promise.resolve();
      balance -= amt;
      return 'ok';
    }
    return 'denied';
  });
  lock = run.catch(() => {});
  return run;
}
Promise.all([withdraw(80), withdraw(80)]).then((r) => console.log(r.join(','), balance));

